var i=`0328-croque-monsieur`;var n=`world-0328`;var o=`FR`;var r=`western-europe`;var s=4;var a=26;var u={en:`Croque Monsieur`,ua:`Крок-месьє`};var d={en:`A traditional France dish made with white bread, smoked ham, gruyère, dijon mustard. This home-style preparation follows its characteristic cooking method and uses measured ingredients.`,ua:`Традиційна страва кухні країни Франція. Основні інгредієнти: білий хліб, копчена шинка, грюєр, діжонська гірчиця. Домашній варіант із характерною технологією та поетапно розподіленими продуктами.`};var l=[{en:`Assemble the cooled components with the listed fillings or toppings. Refrigerate briefly if needed to set the layers.`,ua:`Зберіть охолоджені частини з зазначеними начинками або покриттям. За потреби ненадовго охолодіть для стабілізації шарів.`,t:[`layered-assembly`,`garnishing`],m:9,i:[[`white-bread`,300,`g`],[`smoked-ham`,220,`g`],[`gruyere`,210,`g`],[`dijon-mustard`,35,`g`]]},{en:`Melt the fat, stir in flour and cook gently for about 7 minutes, then whisk in liquid to create a smooth thickened sauce.`,ua:`Розтопіть жир, вмішайте борошно й готуйте на малому вогні приблизно 7 хвилин, потім поступово влийте рідину, збиваючи до гладкого густого соусу.`,t:[`roux-making`],m:7,i:[[`unsalted-butter`,45,`g`],[`all-purpose-flour`,45,`g`],[`whole-cow-milk`,390,`ml`],[`ground-nutmeg`,2,`g`]]},{en:`Roast in a preheated 190°C oven for about 10 minutes until nicely browned and fully cooked; turn once if needed.`,ua:`Запікайте в розігрітій до 190°C духовці приблизно 10 хвилин до рум’яності й готовності; за потреби переверніть.`,t:[`roasting`],m:10,i:[[`gruyere`,70,`g`]]}];var g={slug:i,id:n,country:`FR`,region:r,servings:4,minutes:26,title:u,text:d,steps:l};export{o as country,g as default,n as id,a as minutes,r as region,s as servings,i as slug,l as steps,d as text,u as title};